// spec: .qa/e2e/specs/app-lock.md · тикет #f0cce9 (נעילת אפליקציה) — веб-часть.
// В вебе блокировки нет: строка «נעילת אפליקציה» есть, тумблер выключен и недоступен, подпись «זמין באפליקציה בלבד»
// (коммент программиста 10.11 + #01a5ce), текст Figma 869-8390; AC 8 — отдельно от «אימות פנים».
// Роль new10, iPhone 13 Mini (WebKit). Только просмотр: тумблер не включается (он disabled), данные не меняются.
import { test, expect } from '@playwright/test';
import path from 'path';
import { saveSession } from '../_shared/session';

const ROLE = 'new10';
test.use({ storageState: path.resolve(__dirname, '../../../auth', `${ROLE}.json`) });

test.describe('נעילת אפליקציה — הגדרות (веб)', () => {
  test.afterEach(async ({ page }) => {
    await saveSession(page, ROLE);
  });

  test('«נעילת אפליקציה» в «פרטיות ואבטחה»: тумблер выключен и недоступен, «זמין באפליקציה בלבד», текст 869-8390, отдельно от «אימות פנים» @iphone @prod-safe (#f0cce9)', async ({ page }) => {
    await page.goto('/settings');
    await expect(page.getByText('הגדרות', { exact: true }).first()).toBeVisible();

    // Раздел «פרטיות ואבטחה» и строка в нём.
    await expect(page.getByText('פרטיות ואבטחה', { exact: true })).toBeVisible();
    await expect(page.getByText('נעילת אפליקציה', { exact: true })).toBeVisible();
    await expect(page.getByText('זמין באפליקציה בלבד', { exact: true })).toBeVisible();
    await expect(page.getByText('Face ID, טביעת אצבע או קוד המכשיר — כדי שאף אחד אחר לא יפתח את Magnet בטלפון שלך.')).toBeVisible();

    // Тумблер: выключен и недоступен в вебе.
    const toggle = page.getByRole('switch', { name: 'נעילת אפליקציה' });
    await expect(toggle).toBeVisible();
    await expect(toggle).toHaveAttribute('aria-checked', 'false');
    await expect(toggle).toHaveAttribute('aria-disabled', 'true');

    // Нажатие ничего не включает (без системного окна и без блокировки).
    await toggle.click({ force: true });
    await expect(toggle).toHaveAttribute('aria-checked', 'false');
    await expect(page.getByText('Magnet נעולה')).toHaveCount(0);

    // AC 8: верификация лица — отдельная строка, другой механизм.
    await expect(page.getByRole('button', { name: 'אימות פנים' })).toBeVisible();
    await expect(page.getByRole('switch', { name: 'אימות פנים' })).toHaveCount(0);
  });

  test('после перезагрузки приложение открывается без экрана блокировки «Magnet נעולה» (веб) @iphone @prod-safe (#f0cce9)', async ({ page }) => {
    await page.goto('/discover');
    await expect(page.getByRole('tab', { name: 'הודעות', exact: true })).toBeVisible();
    await page.reload();
    await expect(page.getByRole('tab', { name: 'הודעות', exact: true })).toBeVisible();
    await expect(page.getByText('Magnet נעולה')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'פתיחה' })).toHaveCount(0);
  });
});
